package org.apache.commons.math3.genetics;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.NullArgumentException;
import org.apache.commons.math3.exception.NumberIsTooLargeException;
import org.apache.commons.math3.exception.NumberIsTooSmallException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.mock;

public class ListPopulation_addChromosome_TriageGen1Test {

    @Test
    public void testAddChromosome_Success() {
        // Arrange
        int limit = 5;
        ListPopulation population = new ListPopulation(limit);
        Chromosome chromosome = mock(Chromosome.class);

        // Act
        population.addChromosome(chromosome);

        // Assert
        Assert.assertEquals(1, population.getChromosomes().size());
        Assert.assertTrue(population.getChromosomes().contains(chromosome));
    }

    @Test
    public void testAddChromosome_AtLimit_ThrowsException() {
        // Arrange
        int limit = 2;
        ListPopulation population = new ListPopulation(limit);
        Chromosome c1 = mock(Chromosome.class);
        Chromosome c2 = mock(Chromosome.class);
        Chromosome c3 = mock(Chromosome.class);

        population.addChromosome(c1);
        population.addChromosome(c2);

        // Act & Assert
        try {
            population.addChromosome(c3);
            Assert.fail("Expected NumberIsTooLargeException to be thrown");
        } catch (NumberIsTooLargeException e) {
            // Verify exception details if possible, though we primarily target coverage here
            Assert.assertEquals(limit, population.getPopulationLimit());
        }
    }

    @Test
    public void testAddChromosome_WithExistingList_Success() {
        // Arrange
        int limit = 10;
        List<Chromosome> initialList = new ArrayList<>();
        initialList.add(mock(Chromosome.class));
        initialList.add(mock(Chromosome.class));

        ListPopulation population = new ListPopulation(initialList, limit);
        Chromosome newChromosome = mock(Chromosome.class);

        // Act
        population.addChromosome(newChromosome);

        // Assert
        Assert.assertEquals(3, population.getChromosomes().size());
        Assert.assertEquals(newChromosome, population.getChromosomes().get(2));
    }

    @Test
    public void testAddChromosome_BoundaryCondition_LimitZero() {
        // Arrange
        int limit = 0;
        ListPopulation population = new ListPopulation(limit);
        Chromosome chromosome = mock(Chromosome.class);

        // Act & Assert
        try {
            population.addChromosome(chromosome);
            Assert.fail("Expected NumberIsTooLargeException for limit 0");
        } catch (NumberIsTooLargeException e) {
            // Covered
        }
    }
}
